Solidity.Roadmap.V16.calculus_compiler_s.type:
∀ {C : Solidity.Contract} {b L frame : Nat} {Γ Δ : Solidity.Ctx} {F : Solidity.Evm.Frag Γ} {P : Solidity.Prog C Γ Δ}
  (compiled : Solidity.Evm.Compiler.Compilation b F P) {σ : Solidity.State C Γ} {base : Nat → Fin Solidity.Evm.W}
  {m : Solidity.Evm.Machine} {φ : Solidity.Fml C Δ},
  compiled.Input L frame base σ m →
    Solidity.holds σ (Solidity.Fml.modal Solidity.Modality.diamond P Solidity.Frames.nil φ) →
      ∃ o, Solidity.Prog.run σ P = Except.ok o ∧ Solidity.holds o.st φ
